function get(){let id=sessionStorage.getItem('solop-html-v1-session');if(!id)return null;let book=JSON.parse(localStorage.getItem('solop-html-v1-book-'+id)||'{}').data||{};let key='solop-html-v1-finance-'+id;let fin=JSON.parse(localStorage.getItem(key)||'{}');return {book,key,fin:{...fin,rates:fin.rates||{},payments:fin.payments||[],surcharges:Array.isArray(fin.surcharges)?fin.surcharges:[],studentRates:fin.studentRates||{}}}}
function save(ctx){localStorage.setItem(ctx.key,JSON.stringify(ctx.fin));render()}
function rows(ctx){let {classes=[],students=[],sessions=[],attendance={}}=ctx.book;return students.filter(st=>filter==='all'||st.classId===filter).map(st=>{let cl=classes.find(c=>c.id===st.classId);let own=Object.prototype.hasOwnProperty.call(ctx.fin.studentRates,st.id);let rate=Math.max(0,Number(own?ctx.fin.studentRates[st.id]:ctx.fin.rates[st.classId])||0);let records=sessions.filter(se=>se.classId===st.classId&&se.date?.startsWith(month)).map(se=>({date:se.date,status:attendance[se.id]?.[st.id]?.status||'',note:attendance[se.id]?.[st.id]?.note||''})).filter(x=>['present','late','absent','excused'].includes(x.status)).sort((a,b)=>a.date.localeCompare(b.date));let count=records.filter(x=>x.status==='present'||x.status==='late').length;let tuition=rate*count;let extras=ctx.fin.surcharges.filter(s=>s.studentId===st.id&&s.month===month);let extraTotal=extras.reduce((sum,s)=>sum+Math.max(0,Number(s.amount)||0),0);let due=tuition+extraTotal;let paid=ctx.fin.payments.filter(p=>p.studentId===st.id&&p.month===month).reduce((a,p)=>a+Number(p.amount||0),0);return {st,cl,rate,count,tuition,extras,extraTotal,due,paid,balance:due-paid,records,absences:records.filter(x=>x.status==='absent'||x.status==='excused')}})}
function download(rows){let data=[['Tháng','Học sinh','Lớp','Buổi có mặt/đi muộn','Ngày đi học','Ngày nghỉ','Học phí/buổi','Học phí','Chi tiết phụ phí','Tổng phụ phí','Tổng phải thu','Đã thu','Còn lại'],...rows.map(r=>[month,r.st.name,r.cl?.name||'',r.count,r.records.filter(x=>['present','late'].includes(x.status)).map(x=>viDate(x.date)).join('; '),r.absences.map(x=>viDate(x.date)+(x.status==='excused'?' (có phép)':' (vắng)')).join('; '),r.rate,r.tuition,r.extras.map(x=>x.name+' ('+x.amount+'đ)').join('; '),r.extraTotal,r.due,r.paid,r.balance])];let csv='\ufeff'+data.map(row=>row.map(x=>'"'+String(x).replace(/^[=+@\-\t\r]/,"'").replace(/"/g,'""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='tong-ket-hoc-phi-'+month+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
