(function(){const $=id=>document.getElementById(id),modal=$('tw-modal');const days=['Chủ nhật','Thứ hai','Thứ ba','Thứ tư','Thứ năm','Thứ sáu','Thứ bảy'];for(let id of ['tw-day1','tw-day2'])$(id).innerHTML=days.map((d,i)=>`<option value="${i}">${d}</option>`).join('');$('tw-day1').value='2';$('tw-day2').value='5';$('tw-from').value=new Date().toLocaleDateString('en-CA');function get(){let id=sessionStorage.getItem('solop-html-v1-session');if(!id)return null;let key='solop-html-v1-book-'+id;let raw=JSON.parse(localStorage.getItem(key)||'{}');return {key,raw,data:raw.data||{classes:[],sessions:[],students:[],attendance:{}}}}function open(){let b=get();if(!b)return alert('Vui lòng đăng nhập trước.');$('tw-class').innerHTML=(b.data.classes||[]).map(c=>{let o=document.createElement('option');o.value=c.id;o.textContent=c.name;return o.outerHTML}).join('');if(!b.data.classes?.length)return alert('Bạn cần tạo lớp học trước.');modal.classList.add('open')}function close(){modal.classList.remove('open')}$('tw-cancel').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};$('tw-save').onclick=()=>{let b=get();if(!b)return;let d1=Number($('tw-day1').value),d2=Number($('tw-day2').value),start=$('tw-start').value,end=$('tw-end').value,from=$('tw-from').value,n=Number($('tw-weeks').value),classId=$('tw-class').value;if(d1===d2)return alert('Hãy chọn hai ngày khác nhau.');if(!from||!start||!end||end<=start||!Number.isInteger(n)||n<1||n>52)return alert('Vui lòng kiểm tra ngày, giờ và số tuần (1–52).');let first=new Date(from+'T12:00:00');if(isNaN(first))return alert('Ngày bắt đầu không hợp lệ.');b.data.sessions ||= [];let added=0,skipped=0;for(let w=0;w<n;w++)for(let dow of [d1,d2]){let date=new Date(first);date.setDate(first.getDate()+(dow-first.getDay()+7)%7+7*w);let ds=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');if(b.data.sessions.some(x=>x.classId===classId&&x.date===ds)){skipped++;continue}b.data.sessions.push({id:crypto.randomUUID(),classId,date:ds,start,end,topic:'Buổi học định kỳ'});added++}b.raw.data=b.data;localStorage.setItem(b.key,JSON.stringify(b.raw));alert('Đã tạo '+added+' buổi học. Bỏ qua '+skipped+' ngày đã có lịch cho lớp này.');location.reload()};function attach(){let active=[...document.querySelectorAll('nav button')].some(b=>b.classList.contains('active')&&b.textContent.includes('Lịch học'));let bar=document.querySelector('.weekNav')?.closest('.toolbar');if(active&&bar&&!$('tw-open')){let btn=document.createElement('button');btn.id='tw-open';btn.className='primary';btn.textContent='📅 Tạo lịch 2 buổi/tuần';btn.onclick=open;bar.appendChild(btn)}}new MutationObserver(attach).observe($('root'),{childList:true,subtree:true});setTimeout(attach,500)})();
