/* --- JavaScript 5 --- */

(()=>{'use strict';
const NS='solop-html-v1-',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(Number(n)||0).toLocaleString('vi-VN')+' ₫';
const now=()=>{const d=new Date;return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const user=()=>sessionStorage.getItem(NS+'session');
const k=t=>NS+t+'-'+user();
const safeRead=t=>{try{return JSON.parse(localStorage.getItem(k(t))||'{}')}catch{return {}}};
const getBook=()=>{const raw=safeRead('book');return {raw,data:raw.data||{classes:[],students:[],sessions:[],attendance:{}}}};
const getFinance=()=>{const x=safeRead('finance');return {...x,rates:x.rates||{},studentRates:x.studentRates||{},payments:x.payments||[]}};
const statuses=[['present','Có mặt'],['late','Đi muộn'],['excused','Có phép'],['absent','Vắng'],['','Bỏ chọn']];
let currentClass='',currentDate=now(),draft={},dirty=false,open=false,showHistory=true;
function close(){open=false;document.getElementById('flex-attendance-overlay')?.setAttribute('hidden','');}
function dataForDate(data,cl,day){let ss=(data.sessions||[]).filter(s=>s.classId===cl&&s.date===day);let primary=ss.find(s=>s.topic==='Điểm danh linh hoạt')||ss[0];return primary||null}
function selectView(){const {data}=getBook();if(!data.classes.some(c=>c.id===currentClass))currentClass=data.classes[0]?.id||'';const sess=dataForDate(data,currentClass,currentDate);draft=structuredClone(sess?data.attendance?.[sess.id]||{}:{});dirty=false;render()}
function recentDays(data,cl){return [...new Set((data.sessions||[]).filter(s=>s.classId===cl&&Object.values(data.attendance?.[s.id]||{}).some(x=>x.status)).map(s=>s.date))].sort().reverse().slice(0,16)}
function render(){if(!open)return;const el=document.getElementById('flex-attendance-overlay');if(!el)return;const {data}=getBook();const cs=data.classes||[],st=(data.students||[]).filter(s=>s.classId===currentClass),ss=dataForDate(data,currentClass,currentDate),fee=getFinance();
const counts=statuses.slice(0,4).map(([v])=>st.filter(s=>draft[s.id]?.status===v).length);
const recent=recentDays(data,currentClass);
el.innerHTML=`<div class="flex-head"><div><div class="flex-kicker">SỔ LỚP · KHÔNG CẦN LỊCH CỐ ĐỊNH</div><h1>Điểm danh theo ngày thực tế</h1><p>Chọn lớp và ngày học bất kỳ để ghi nhận điểm danh, không cần tạo thời khóa biểu.</p></div><button id="flex-go-back" class="subtle" type="button">← Quay lại</button></div>
<div class="flex-controls"><label>Lớp học<select id="flex-choose-class">${cs.map(c=>`<option value="${esc(c.id)}" ${currentClass===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Ngày điểm danh<input type="date" id="flex-choose-date" value="${esc(currentDate)}"></label><button type="button" class="subtle" id="flex-today">Hôm nay</button></div>
<div class="flex-panel"><h2>Danh sách học sinh <span class="pill">${st.length} học sinh</span></h2><p class="flex-muted">${ss?'Đang xem điểm danh đã lưu. Bạn có thể chỉnh lại trạng thái.':'Chưa có điểm danh trong ngày này.'} Chỉ chọn trạng thái cho học sinh thực sự có lịch học trong ngày; học sinh không học ngày đó thì để trống.</p>
${st.length?`<div class="flex-table-wrap"><table class="flex-table"><thead><tr><th>Học sinh</th><th>Trạng thái</th><th>Ghi chú (tuỳ chọn)</th></tr></thead><tbody>${st.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td><div class="flex-statuses">${statuses.map(([value,label])=>`<button type="button" data-student="${esc(s.id)}" data-status="${esc(value)}" class="${(draft[s.id]?.status||'')===value?'on':''}">${label}</button>`).join('')}</div></td><td><input class="flex-note" data-note-student="${esc(s.id)}" value="${esc(draft[s.id]?.note||'')}" maxlength="250" placeholder="Ghi chú..."></td></tr>`).join('')}</tbody></table></div>`:'<p>Chưa có học sinh trong lớp này. Hãy vào phần Lớp học / Học sinh để thêm học sinh.</p>'}
<div class="flex-summary"><span>Có mặt: <b>${counts[0]}</b></span><span>Đi muộn: <b>${counts[1]}</b></span><span>Có phép: <b>${counts[2]}</b></span><span>Vắng: <b>${counts[3]}</b></span><span>Chưa đánh dấu: <b>${st.length-counts.reduce((a,b)=>a+b,0)}</b></span></div><div class="flex-bottom"><p class="flex-muted" id="flex-save-hint">${dirty?'Có thay đổi chưa lưu.':'Học phí chỉ tính những ngày được đánh dấu Có mặt hoặc Đi muộn.'}</p><button type="button" class="primary" id="flex-save" ${st.length?'':'disabled'}>Lưu điểm danh</button></div></div>
<div class="flex-panel"><h2>Ngày đã điểm danh của lớp</h2><p class="flex-muted">Chọn ngày để xem hoặc sửa lại. Ngày chưa ghi nhận sẽ không tự bị tính là vắng.</p>${recent.length?recent.map(day=>`<div class="flex-history-item"><span>${day.split('-').reverse().join('/')}</span><button data-open-day="${esc(day)}" type="button" class="subtle">Xem / Sửa</button></div>`).join(''):'<p class="flex-muted" style="margin-top:14px">Chưa có ngày nào được điểm danh.</p>'}</div>`;
el.querySelector('#flex-go-back').onclick=close;
el.querySelector('#flex-choose-class').onchange=e=>{if(!confirmDiscard())return selectView();currentClass=e.target.value;selectView()};
el.querySelector('#flex-choose-date').onchange=e=>{if(!e.target.value||!/^\d{4}-\d{2}-\d{2}$/.test(e.target.value)||!confirmDiscard())return selectView();currentDate=e.target.value;selectView()};
el.querySelector('#flex-today').onclick=()=>{if(!confirmDiscard())return;currentDate=now();selectView()};
el.querySelectorAll('[data-open-day]').forEach(b=>b.onclick=()=>{if(!confirmDiscard())return;currentDate=b.dataset.openDay;selectView();el.scrollTo({top:0,behavior:'smooth'})});
el.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{const id=b.dataset.student,status=b.dataset.status;draft[id]={...(draft[id]||{}),status,note:draft[id]?.note||''};if(!status&&!draft[id].note)delete draft[id];dirty=true;render()});
el.querySelectorAll('[data-note-student]').forEach(inp=>inp.oninput=()=>{const id=inp.dataset.noteStudent;draft[id]={...(draft[id]||{}),note:inp.value};dirty=true;let hint=el.querySelector('#flex-save-hint');if(hint)hint.textContent='Có thay đổi chưa lưu.'});
el.querySelector('#flex-save').onclick=save;
}
function confirmDiscard(){return !dirty||confirm('Bạn có thay đổi điểm danh chưa lưu. Bỏ các thay đổi này?')}
function save(){if(!user())return alert('Vui lòng đăng nhập.');if(!currentClass||!/^\d{4}-\d{2}-\d{2}$/.test(currentDate))return alert('Chọn lớp và ngày hợp lệ.');let {raw,data}=getBook();if(!data.classes.some(c=>c.id===currentClass))return alert('Lớp không tồn tại.');const students=new Set(data.students.filter(s=>s.classId===currentClass).map(s=>s.id)),clean={};for(let [id,mark] of Object.entries(draft)){if(!students.has(id))continue;let status=mark?.status||'',note=String(mark?.note||'').trim().slice(0,250);if(status&&!statuses.slice(0,4).some(x=>x[0]===status))return alert('Trạng thái không hợp lệ.');if(note&&!status)return alert('Hãy chọn trạng thái điểm danh cho học sinh trước khi lưu ghi chú.');if(status)clean[id]={status,note}}
const hasMarks=Object.values(clean).some(x=>x.status);
let session=dataForDate(data,currentClass,currentDate);if(!session&&hasMarks){session={id:globalThis.crypto?.randomUUID?.()||'flex-'+Date.now(),classId:currentClass,date:currentDate,start:'00:00',end:'00:01',topic:'Điểm danh linh hoạt'};data.sessions.push(session)}
if(session){if(Object.keys(clean).length)data.attendance[session.id]=clean;else delete data.attendance[session.id];
// Xóa buổi kỹ thuật nếu tất cả điểm danh đã bỏ chọn, không xóa buổi học cũ do người dùng lập.
if(session.topic==='Điểm danh linh hoạt'&&!hasMarks)data.sessions=data.sessions.filter(s=>s.id!==session.id)}
try{localStorage.setItem(k('book'),JSON.stringify({data,revision:(Number(raw.revision)||0)+1}));dirty=false;sessionStorage.setItem(NS+'reopen-flex','1');sessionStorage.setItem(NS+'flex-return-selection',JSON.stringify({classId:currentClass,date:currentDate}));location.reload()}catch(e){alert('Không thể lưu điểm danh: '+(e.message||'Kiểm tra bộ nhớ trình duyệt.'))}
}
function openAttendance(){if(!user()){alert('Vui lòng đăng nhập để điểm danh.');return}document.getElementById('finance-overlay')?.setAttribute('hidden','');document.getElementById('addon-panel')?.setAttribute('hidden','');open=true;selectView();document.getElementById('flex-attendance-overlay').removeAttribute('hidden');}
function financeModal(classId){
 if(!user())return;
 const data=getBook().data,cs=data.classes||[],c=cs.find(x=>x.id===classId);
 if(!c)return;
 document.getElementById('flex-fee-dialog')?.remove();
 const fin=getFinance(),people=(data.students||[]).filter(st=>st.classId===classId);
 const box=document.createElement('div');box.id='flex-fee-dialog';box.className='flex-dialog-backdrop';
 box.innerHTML=`<div class="flex-dialog flex-individual-fee-dialog"><div class="flex-kicker">LỚP HỌC · HỌC PHÍ CÁ NHÂN</div><h2>Học phí lớp ${esc(c.name)}</h2><p class="flex-muted">Trong cùng một lớp, mỗi học sinh có thể được áp dụng một mức học phí khác nhau.</p>
 <form id="flex-fee-form"><div class="flex-default-rate"><label>Học phí chung của lớp (VNĐ / buổi)<input name="rate" type="number" min="0" max="1000000000" step="1" value="${Number(fin.rates[c.id]||0)}" required></label><small>Học sinh không có mức riêng sẽ dùng mức này.</small></div>
 <div class="flex-people-fees"><h3>Học phí theo từng học sinh <span class="pill">${people.length} học sinh</span></h3>${people.map(st=>{const own=Object.prototype.hasOwnProperty.call(fin.studentRates,st.id);return `<label class="flex-person-fee"><span><strong>${esc(st.name)}</strong><small>${own?'Mức riêng đang áp dụng':'Đang theo học phí lớp'}</small></span><span class="flex-person-input"><input data-person-fee="${esc(st.id)}" type="number" min="0" max="1000000000" step="1" value="${own?Number(fin.studentRates[st.id]):''}" placeholder="Theo lớp" aria-label="Học phí mỗi buổi của ${esc(st.name)}"><small>₫ / buổi</small></span></label>`}).join('')||'<p class="flex-muted">Hãy thêm học sinh vào lớp để thiết lập học phí riêng.</p>'}</div>
 <p class="flex-muted">Để trống mức riêng = lấy học phí chung của lớp. Nhập số <b>0</b> nếu muốn miễn học phí cho học sinh đó.</p><div class="flex-dialog-actions"><button type="button" class="subtle" id="flex-fee-cancel">Hủy</button><button type="submit" class="primary">Lưu học phí</button></div></form></div>`;
 document.body.append(box);
 box.querySelector('#flex-fee-cancel').onclick=()=>box.remove();box.onclick=e=>{if(e.target===box)box.remove()};
 box.querySelector('#flex-fee-form').onsubmit=e=>{
  e.preventDefault();const n=Number(e.target.elements.rate.value);
  if(!Number.isSafeInteger(n)||n<0||n>1000000000)return alert('Học phí lớp phải là số nguyên từ 0 đến 1 tỷ đồng.');
  const newRates={...fin.studentRates};
  for(const input of box.querySelectorAll('[data-person-fee]')){
   if(input.value.trim()===''){delete newRates[input.dataset.personFee];continue}
   const individual=Number(input.value);
   if(!Number.isSafeInteger(individual)||individual<0||individual>1000000000){input.focus();return alert('Học phí riêng phải là số nguyên từ 0 đến 1 tỷ đồng.');}
   newRates[input.dataset.personFee]=individual;
  }
  fin.rates[c.id]=n;fin.studentRates=newRates;
  try{localStorage.setItem(k('finance'),JSON.stringify(fin));box.remove();injectClassFees(true)}catch{alert('Không thể lưu học phí.')}
 };
}

function injectClassFees(force){if(!user())return;const nav=document.querySelector('.sidebar nav');if(!nav)return;for(const btn of nav.querySelectorAll('button')){
const text=(btn.textContent||'').trim();if(text==='Lịch học'||btn.dataset.page==='quick12')btn.style.display='none';
}
const isClasses=[...nav.querySelectorAll('button.active')].some(b=>/Lớp học/.test(b.textContent||''));const grid=document.querySelector('.classGrid'),detail=document.querySelector('.classDetail');const root=document.getElementById('root');if(!root||!isClasses||(!grid&&!detail))return;
const cs=getBook().data.classes||[],fin=getFinance();let container=(grid||detail),previous=document.getElementById('flex-classes-fees');if(previous&&previous.parentElement!==container.parentElement)previous.remove();
if(!document.getElementById('flex-classes-fees')){let card=document.createElement('div');card.id='flex-classes-fees';card.className='flex-fee-card';container.parentNode.insertBefore(card,container)}
const panel=document.getElementById('flex-classes-fees');if(force||panel.dataset.serial!==JSON.stringify(cs.map(c=>[c.id,c.name,fin.rates[c.id]||0,(getBook().data.students||[]).filter(st=>st.classId===c.id).map(st=>[st.id,fin.studentRates[st.id]])]))){panel.dataset.serial=JSON.stringify(cs.map(c=>[c.id,c.name,fin.rates[c.id]||0,(getBook().data.students||[]).filter(st=>st.classId===c.id).map(st=>[st.id,fin.studentRates[st.id]])]));panel.innerHTML=`<div class="flex-fee-actions"><div><h3>Học phí theo lớp và từng học sinh</h3><p>Mỗi học sinh trong cùng một lớp có thể có đơn giá riêng / buổi.</p></div></div><div class="flex-fee-grid">${cs.map(c=>`<div class="flex-fee-item"><strong>${esc(c.name)}</strong><b>${fmt(fin.rates[c.id]||0)} / buổi (mức lớp)</b><small>${(getBook().data.students||[]).filter(st=>st.classId===c.id&&Object.prototype.hasOwnProperty.call(fin.studentRates,st.id)).length} học sinh có mức riêng</small><button type="button" class="subtle" data-class-fee="${esc(c.id)}">Chỉnh từng học sinh</button></div>`).join('')||'<p>Hãy tạo lớp trước khi thiết lập học phí.</p>'}</div>`;panel.querySelectorAll('[data-class-fee]').forEach(b=>b.onclick=()=>financeModal(b.dataset.classFee))}
// Hiện đơn giá dưới tên mỗi lớp (không nhúng nút tương tác vào tile vì tile có thể là button).
if(grid){for(const tile of grid.querySelectorAll('.classTile')){const name=tile.querySelector('strong')?.textContent?.trim(),cls=cs.find(c=>c.name===name);if(!cls)continue;let price=tile.querySelector('.flex-inline-price');if(!price){price=document.createElement('span');price.className='flex-inline-price';tile.appendChild(price)}price.textContent='Mức lớp: '+fmt(fin.rates[cls.id]||0)+'/buổi · Có thể đặt riêng từng học sinh'}}
}
function bootstrap(){if(!document.getElementById('flex-attendance-overlay')){const el=document.createElement('section');el.id='flex-attendance-overlay';el.setAttribute('hidden','');document.body.append(el)}injectClassFees(false);
// Các nút lối tắt của giao diện cũ chuyển sang điểm danh linh hoạt.
for(const btn of document.querySelectorAll('#root main button')){const text=(btn.textContent||'').trim();if(text==='Thêm lịch học'){
let tn=[...btn.childNodes].filter(x=>x.nodeType===Node.TEXT_NODE);if(tn.length)tn[tn.length-1].textContent='Điểm danh theo ngày';else btn.textContent='Điểm danh theo ngày';
}else if(text==='Xem lịch'){
let tn=[...btn.childNodes].filter(x=>x.nodeType===Node.TEXT_NODE);if(tn.length)tn[tn.length-1].textContent='Xem điểm danh';else btn.textContent='Xem điểm danh';
}}
}
// Capture click trước React: điểm danh trực tiếp mà không mở lịch học.
document.addEventListener('click',e=>{const btn=e.target.closest?.('button');if(!btn)return;const label=(btn.textContent||'').trim();const nativeNav=!!btn.closest('.sidebar nav');const gotoFlexible=nativeNav?/Điểm danh/.test(label):['Điểm danh theo ngày','Xem điểm danh','Thêm lịch học','Xem lịch'].includes(label);if(gotoFlexible){e.preventDefault();e.stopImmediatePropagation();openAttendance()}},true);
let lock=false;new MutationObserver(()=>{if(lock)return;lock=true;requestAnimationFrame(()=>{lock=false;bootstrap()})}).observe(document.getElementById('root'),{subtree:true,childList:true});
bootstrap();
if(sessionStorage.getItem(NS+'reopen-flex')==='1'){sessionStorage.removeItem(NS+'reopen-flex');try{const sel=JSON.parse(sessionStorage.getItem(NS+'flex-return-selection')||'{}');if(sel.classId)currentClass=sel.classId;if(/^\d{4}-\d{2}-\d{2}$/.test(sel.date||''))currentDate=sel.date}catch{}sessionStorage.removeItem(NS+'flex-return-selection');let tries=0;const timer=setInterval(()=>{if(user()){clearInterval(timer);openAttendance()}else if(++tries>30)clearInterval(timer)},150)}
window.SoLopFlexible={open:openAttendance,close,editClassFee:financeModal};
// Hiển thị ngày/tháng/năm đầy đủ ở phần tiêu đề của giao diện cơ bản.
function showFullCalendarDate(){const header=document.querySelector('#root header');if(!header)return;let label=header.querySelector('.solop-header-date');if(!label){label=document.createElement('span');label.className='solop-header-date';header.append(label)}{const today='📅 '+new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date());if(label.textContent!==today)label.textContent=today}}
new MutationObserver(showFullCalendarDate).observe(document.getElementById('root'),{subtree:true,childList:true});showFullCalendarDate();
})();

;


/* ===============================================================
   Hoa pastel chuyển động riêng cho trang đăng nhập / đăng ký.
   Toàn bộ lớp trang trí ở ngoài #root để không ảnh hưởng React.
   =============================================================== */
(()=>{
  const root=document.getElementById('root');
  if(!root)return;
  const effects=document.createElement('div');
  effects.id='sl-auth-effects';
  effects.hidden=true;
  effects.setAttribute('aria-hidden','true');
  // Các vị trí cố định, không dùng random: hiển thị nhất quán khi mở trang.
  const petals=[
    [3,13,18,-1,18,20],[14,10,17,-9,-37,-20],[25,12,23,-13,27,35],
    [36,8,15,-2,-16,-50],[46,12,21,-11,34,-16],[59,9,18,-4,-31,62],
    [67,11,24,-18,20,-28],[76,8,19,-8,-21,48],[86,13,22,-15,36,16],
    [95,10,17,-6,-35,-42],[43,7,25,-23,29,20],[8,8,26,-18,24,-32]
  ];
  petals.forEach(([x,w,time,delay,drift,angle])=>{
    const petal=document.createElement('span');
    petal.className='sl-petal';
    petal.style.cssText=`--petal-x:${x}%;--petal-w:${w}px;--petal-time:${time}s;--petal-delay:${delay}s;--petal-drift:${drift}px;--petal-angle:${angle}deg`;
    effects.appendChild(petal);
  });
  document.body.appendChild(effects);
  const modes=new WeakMap();
  let raf=0;
  function sync(){
    raf=0;
    const auth=root.querySelector('.authPage:not(.profilePage)');
    effects.hidden=!auth;
    if(!auth)return;
    const card=auth.querySelector('.authCard');
    if(!card)return;
    const active=auth.querySelector('.authSwitch button.chosen');
    const mode=active?active.textContent.trim():'';
    const previous=modes.get(card);
    if(previous===undefined){modes.set(card,mode);return;}
    if(previous===mode)return;
    modes.set(card,mode);
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    card.classList.remove('sl-mode-animating');
    // Kích hoạt lại animation khi đổi giữa Đăng nhập và Đăng ký.
    void card.offsetWidth;
    card.classList.add('sl-mode-animating');
    window.setTimeout(()=>card.classList.remove('sl-mode-animating'),490);
  }
  const observer=new MutationObserver(()=>{
    if(raf)return;
    raf=requestAnimationFrame(sync);
  });
  observer.observe(root,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});
  sync();
})();
